    /// Whether `path` is throttled (its interval is above the base).
    pub(crate) fn is_throttled(&self, path: &Path) -> bool {
        self.paths
            .get(path)
            .is_some_and(|schedule| schedule.interval > self.limits.base)
    }

    /// A change to `path` was seen.
