    needs: [gate, build-tarball-linux]
    # The auto-merge-enabled release PR already tests this exact release
    # candidate. Do not repeat the full suite when its tag is published.
    if: needs.gate.outputs.build == 'true' && !startsWith(github.ref, 'refs/tags/v')
    name: e2e-linux-${{matrix.tranche}}
    runs-on: ubuntu-latest
    #container: ghcr.io/jdx/mise:github-actions
    timeout-minutes: 30
    strategy:
      fail-fast: false
      matrix:
        tranche: [0, 1, 2, 3, 4, 5, 6, 7]
    steps:
      - uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1 # v7
      - name: Install zsh/fish/direnv/fd
        run: sudo apt-get update; sudo apt-get install zsh fish direnv fd-find liblzma-dev libbz2-dev
      - name: Install fd-find
        run: |
          mkdir -p "$HOME/.local/bin"
          ln -s "$(which fdfind)" "$HOME/.local/bin/fd"
          echo "$HOME/.local/bin" >> "$GITHUB_PATH"
  "reqwest/rustls",
  "rattler/rustls",
  "rattler_repodata_gateway/rustls",
  "mise-sigstore/rustls",
  "mise-cache-core/rustls",
  "ubi/rustls-tls",
  "vfox/rustls",
  "xx/rustls",
  "self_update?/rustls",
]
rustls-native-roots = [
  "gix/blocking-http-transport-reqwest-rust-tls",
  "reqwest/rustls",
  "rattler/rustls",
  "rattler_repodata_gateway/rustls",
  "mise-sigstore/rustls",
  "mise-cache-core/rustls-native-roots",
  "ubi/rustls-tls",
  "vfox/rustls-native-roots",
  "xx/rustls-native-roots",
  "self_update?/rustls",
]

